503	        BigDecimal charged = BigDecimal.ZERO;
504	        BigDecimal unpaidInterest = BigDecimal.ZERO;
505	        BigDecimal unpaidFee = BigDecimal.ZERO;
506	        boolean feeCharged = false;
507	        LocalDate from = dueDate;
508	        for (Part part : inOrder) {
509	            if (!feeCharged && !part.on().isBefore(overdueOn)) {
510	                unpaidFee = fee;
511	                feeCharged = true;
512	            }
513	            BigDecimal toFee = part.amount().min(unpaidFee).max(BigDecimal.ZERO);
514	            unpaidFee = unpaidFee.subtract(toFee);
515	            BigDecimal rest = part.amount().subtract(toFee);
516	            if (earnsInterest && part.on().isAfter(dueDate) && owed.signum() > 0) {
517	                BigDecimal earned = interestOn(owed, daily, ChronoUnit.DAYS.between(from, part.on()));
518	                charged = charged.add(earned);
519	                unpaidInterest = unpaidInterest.add(earned);
520	                from = part.on();
521	            }
522	            BigDecimal toInterest = rest.min(unpaidInterest).max(BigDecimal.ZERO);
523	            unpaidInterest = unpaidInterest.subtract(toInterest);
524	            owed = owed.subtract(rest.subtract(toInterest));
525	        }
526	        if (earnsInterest && owed.signum() > 0) {
527	            charged = charged.add(interestOn(owed, daily, ChronoUnit.DAYS.between(from, today)));
528	        }
529	        this.lateFee = fee;
530	        this.lateInterest = charged;
531	    }
