533	    /** The interest the balance earns over the days at the daily growth factor, rounded half up to the cent. */
534	    private BigDecimal interestOn(BigDecimal balance, BigDecimal daily, long days) {
535	        if (days <= 0) {
536	            return zero();
537	        }
538	        return balance.multiply(daily.pow((int) days, MathContext.DECIMAL128).subtract(BigDecimal.ONE))
539	                .setScale(scale(), RoundingMode.HALF_UP);
540	    }
