542	    /**
543	     * The early-payment discount on offer at the tax rate: the client's early-payment percentage of the
544	     * grand total, rounded down to the cent; nothing for a credit note, or an invoice holding back
545	     * retention or spread over instalments.
546	     */
547	    public BigDecimal earlyDiscount(BigDecimal taxRate) {
548	        if (isCreditNote() || hasPlan() || retentionPct.signum() > 0 || earlyPayDays == null
549	                || earlyPayPct == null || earlyPayPct.signum() <= 0) {
550	            return zero();
551	        }
552	        return total(taxRate).multiply(earlyPayPct).divide(BigDecimal.valueOf(100)).setScale(scale(), RoundingMode.DOWN);
553	    }
