559	    public boolean isEarlyWindowOpen(LocalDate on, BigDecimal taxRate) {
560	        return status == InvoiceStatus.SENT && issueDate != null && getEarlyDiscountTaken().signum() == 0
561	                && earlyDiscount(taxRate).signum() > 0 && !on.isAfter(issueDate.plusDays(earlyPayDays));
