565	     * What would settle the invoice on the given day once the given amount has been paid: what is due
566	     * less the early discount while the early window is open; null when it is not.
567	     */
568	    public BigDecimal settleAmount(BigDecimal paid, BigDecimal taxRate, LocalDate on) {
569	        BigDecimal due = amountDue(paid, taxRate);
570	        if (!isEarlyWindowOpen(on, taxRate) || due.signum() <= 0) {
571	            return null;
572	        }
573	        return due.subtract(earlyDiscount(taxRate)).max(zero());
574	    }
