607	    /**
608	     * The plan's schedule at the tax rate, an ordinary loan of the grand total; empty when there is no
609	     * plan. With the monthly rate i (the annual rate / 12 / 100) the instalment is P x i / (1 - (1 +
610	     * i)^-n), or P / n at 0%, rounded half up to the cent. Each month's interest is the balance still
611	     * owed x i, rounded half up to the cent, and its principal the instalment less the interest; the
612	     * last instalment pays off the whole balance left plus its interest, so the schedule ends at zero.
613	     * Instalment k falls due k months after the issue date, on the same day (the month's last day when
614	     * it is shorter).
615	     */
616	    public List<Instalment> schedule(BigDecimal taxRate) {
617	        if (!hasPlan()) {
618	            return List.of();
619	        }
620	        MathContext mc = MathContext.DECIMAL128;
621	        BigDecimal principal = total(taxRate);
622	        BigDecimal i = instalmentRate.divide(BigDecimal.valueOf(1200), mc);
623	        int n = instalments;
624	        BigDecimal payment;
625	        if (i.signum() == 0) {
626	            payment = principal.divide(BigDecimal.valueOf(n), scale(), RoundingMode.HALF_UP);
627	        } else {
628	            BigDecimal growth = BigDecimal.ONE.add(i).pow(n, mc);
629	            payment = principal.multiply(i).multiply(growth)
630	                    .divide(growth.subtract(BigDecimal.ONE), mc).setScale(scale(), RoundingMode.HALF_UP);
631	        }
632	        List<Instalment> schedule = new ArrayList<>(n);
633	        BigDecimal balance = principal.setScale(scale(), RoundingMode.HALF_UP);
634	        for (int k = 1; k <= n; k++) {
635	            BigDecimal interest = balance.multiply(i).setScale(scale(), RoundingMode.HALF_UP);
636	            BigDecimal paid = k == n ? balance.add(interest) : payment;
637	            BigDecimal repaid = paid.subtract(interest);
638	            balance = balance.subtract(repaid);
639	            LocalDate due = issueDate == null ? null : issueDate.plusMonths(k);
640	            schedule.add(new Instalment(k, due, paid, interest, repaid, balance));
641	        }
642	        return schedule;
643	    }
