645	    /** The plan total at the tax rate: the sum of the instalments; null when there is no plan. */
646	    public BigDecimal planTotal(BigDecimal taxRate) {
647	        if (!hasPlan()) {
648	            return null;
649	        }
650	        return schedule(taxRate).stream().map(Instalment::payment).reduce(zero(), BigDecimal::add);
651	    }
