653	    /**
654	     * Each instalment of the plan at the tax rate once the given amount has been paid, on the given
655	     * day: payments (with what credit notes took off and anything written off) pay the instalments in
656	     * order, each paid off before the next. An instalment not paid off more than {@link #GRACE_DAYS}
657	     * days after its due date is overdue; empty when there is no plan.
658	     */
659	    public List<Instalment.Progress> instalmentProgress(BigDecimal paid, BigDecimal taxRate, LocalDate today) {
660	        List<Instalment.Progress> progress = new ArrayList<>();
661	        BigDecimal left = paid.add(getCredited()).add(writtenOff(paid, taxRate));
662	        for (Instalment instalment : schedule(taxRate)) {
663	            BigDecimal part = left.min(instalment.payment()).max(BigDecimal.ZERO).setScale(scale(), RoundingMode.HALF_UP);
664	            left = left.subtract(part);
665	            BigDecimal unpaid = instalment.payment().subtract(part);
666	            Instalment.Status status;
667	            if (unpaid.signum() <= 0) {
668	                status = Instalment.Status.PAID;
669	            } else if (instalment.dueDate() != null && today.isAfter(instalment.dueDate().plusDays(GRACE_DAYS))) {
670	                status = Instalment.Status.OVERDUE;
671	            } else if (part.signum() > 0) {
672	                status = Instalment.Status.PART_PAID;
673	            } else {
674	                status = Instalment.Status.DUE;
675	            }
676	            progress.add(new Instalment.Progress(instalment, part, unpaid, status));
677	        }
678	        return progress;
679	    }
