681	    /**
682	     * What is overdue at the tax rate once the given amount has been paid, on the given day: for a plan,
683	     * only what is unpaid on its overdue instalments; otherwise all that is due when it is overdue.
684	     */
685	    public BigDecimal overdueAmount(BigDecimal paid, BigDecimal taxRate, LocalDate today) {
686	        if (statusWhenPaid(paid, taxRate, today) != InvoiceStatus.OVERDUE) {
687	            return zero();
688	        }
689	        if (!hasPlan()) {
690	            return amountDue(paid, taxRate);
691	        }
692	        return instalmentProgress(paid, taxRate, today).stream()
693	                .filter(p -> p.status() == Instalment.Status.OVERDUE).map(Instalment.Progress::unpaid)
694	                .reduce(zero(), BigDecimal::add);
695	    }
