798	    /**
799	     * As {@link #statusWhenPaid(BigDecimal, BigDecimal, LocalDate)}, but a fully paid invoice whose
800	     * paid date (null when not known) is after its due date is paid late.
801	     */
802	    public InvoiceStatus statusWhenPaid(BigDecimal paid, LocalDate paidOn, BigDecimal taxRate, LocalDate today) {
803	        if (status != InvoiceStatus.SENT) {
804	            return status;
805	        }
806	        BigDecimal amountDue = amountDue(paid, taxRate);
807	        boolean due = amountDue.signum() > 0;
808	        BigDecimal retentionDue = amountDue.min(retentionReleased(taxRate)).max(BigDecimal.ZERO);
809	        boolean restDue = amountDue.subtract(retentionDue).signum() > 0;
810	        if (hasPlan()) {
811	            if (due && instalmentProgress(paid, taxRate, today).stream()
812	                    .anyMatch(p -> p.status() == Instalment.Status.OVERDUE)) {
813	                return InvoiceStatus.OVERDUE;
814	            }
815	        } else if (restDue && dueDate != null && today.isAfter(dueDate.plusDays(GRACE_DAYS))) {
816	            return InvoiceStatus.OVERDUE;
817	        }
818	        if (retentionDue.signum() > 0 && today.isAfter(retentionDueDate().plusDays(GRACE_DAYS))) {
819	            return InvoiceStatus.OVERDUE;
820	        }
821	        if (!due && retentionHeld(taxRate).signum() > 0) {
822	            return InvoiceStatus.RETENTION_HELD;
823	        }
824	        if (paid.signum() <= 0) {
825	            return !due && getCredited().signum() > 0 ? InvoiceStatus.CREDITED : status;
826	        }
827	        if (due) {
828	            return InvoiceStatus.PART_PAID;
829	        }
830	        return paidOn != null && dueDate != null && paidOn.isAfter(dueDate) ? InvoiceStatus.PAID_LATE
831	                : InvoiceStatus.PAID;
832	    }
