834	    /**
835	     * The date the invoice was fully paid: the date of the payment that cleared its grand total at the
836	     * tax rate, taking the parts of payments (not reversed) in the order they were applied (credit used
837	     * counts on the day it was applied); null while something is still due or retention is held.
838	     */
839	    public LocalDate paidOn(List<Payment> payments, BigDecimal taxRate) {
840	        BigDecimal total = payable(taxRate);
841	        if (status != InvoiceStatus.SENT || total.signum() <= 0 || retentionHeld(taxRate).signum() > 0) {
842	            return null;
843	        }
844	        record Part(LocalDate on, Long paymentId, BigDecimal amount) {
845	        }
846	        List<Part> inOrder = payments.stream().filter(p -> !p.isReversed())
847	                .flatMap(p -> p.getAllocations().stream().filter(a -> a.getInvoiceId().equals(id))
848	                        .map(a -> new Part(a.getDate() == null ? p.getDate() : a.getDate(), p.getId(), a.getAmount())))
849	                .sorted(Comparator.comparing(Part::on).thenComparing(Part::paymentId)).toList();
850	        BigDecimal sum = BigDecimal.ZERO;
851	        for (Part p : inOrder) {
852	            sum = sum.add(p.amount());
853	            if (sum.signum() > 0 && isSmallEnoughToWriteOff(total.subtract(sum))) {
854	                return p.on();
855	            }
856	        }
857	        return null;
858	    }
