860	    /**
861	     * What is still due once the given amount has been paid: the grand total less it, less what credit
862	     * notes have credited, less the retention still held, less anything written off — so nothing once
863	     * payments leave less than {@link #WRITE_OFF_LIMIT}. A credit note itself has nothing due.
864	     */
865	    public BigDecimal amountDue(BigDecimal paid, BigDecimal taxRate) {
866	        if (isCreditNote()) {
867	            return zero();
868	        }
869	        return payable(taxRate).subtract(paid).subtract(writtenOff(paid, taxRate));
870	    }
