872	    /**
873	     * What is written off once the given amount has been paid: when payments leave less than
874	     * {@link #WRITE_OFF_LIMIT} still due, all of what is left; otherwise nothing.
875	     */
876	    public BigDecimal writtenOff(BigDecimal paid, BigDecimal taxRate) {
877	        BigDecimal left = payable(taxRate).subtract(paid);
878	        return !isCreditNote() && paid.signum() > 0 && left.signum() > 0 && isSmallEnoughToWriteOff(left)
879	                ? left.setScale(scale(), RoundingMode.HALF_UP)
880	                : zero();
881	    }
