888	    /**
889	     * Whether paying the amount on top of what was already paid is too small a part payment: under
890	     * {@link #minimumPart} while leaving something still due (what would be written off counts as settled).
891	     * For a plan the least is instead what is still unpaid on its earliest unpaid instalment.
892	     */
893	    public boolean isTooSmallPart(BigDecimal amount, BigDecimal paid, BigDecimal taxRate) {
894	        if (hasPlan()) {
895	            return amount.compareTo(earliestUnpaid(paid, taxRate)) < 0
896	                    && amountDue(paid.add(amount), taxRate).signum() > 0;
897	        }
898	        return amount.compareTo(minimumPart(taxRate)) < 0 && amountDue(paid.add(amount), taxRate).signum() > 0;
899	    }
