940	        BigDecimal changed = new InvoiceLine(description, qty, unitPrice, taxExempt, discountPct, taxRate).amount(scale());
941	        BigDecimal left = subtotal().subtract(line.amount(scale())).add(changed);
942	        if (discountAmount.signum() > 0 && left.compareTo(discountAmount) < 0) {
943	            throw new InvoiceRejectedException("This line cannot be changed: the "
944	                    + currency().format(left) + " subtotal would be less than the "
