951	    /**
952	     * The sum of the line amounts, each after its own discount and already to the cent — so the subtotal
953	     * matches what a client gets by adding up the lines shown.
954	     */
955	    public BigDecimal subtotal() {
956	        return lines.stream().map(l -> l.amount(scale()))
957	                .reduce(zero(), BigDecimal::add);
958	    }
959	
960	    /**
961	     * The amount taken off: the fixed amount when there is one (never more than the subtotal, should
962	     * lines have been changed since), otherwise the discount percentage of the subtotal, rounded down
963	     * to the cent. When there is a cap, it limits everything taken off — the line discounts plus
964	     * this — so this shrinks to what the line discounts leave under the cap, never below zero.
965	     */
966	    public BigDecimal discount() {
967	        BigDecimal discount = discountAmount.signum() > 0
968	                ? discountAmount.min(subtotal()).setScale(scale(), RoundingMode.HALF_UP)
969	                : subtotal().multiply(discountPct).divide(BigDecimal.valueOf(100)).setScale(scale(), RoundingMode.DOWN);
970	        if (discountCap == null) {
971	            return discount;
972	        }
973	        BigDecimal lineDiscounts = lines.stream().map(l -> l.discount(scale()))
974	                .reduce(zero(), BigDecimal::add);
975	        BigDecimal left = discountCap.setScale(scale(), RoundingMode.HALF_UP).subtract(lineDiscounts).max(zero());
976	        return discount.min(left);
977	    }
978	
979	    /**
980	     * Each line's share of the discount, in the order of the lines. The discount's cents are split in
981	     * proportion to the line amounts: each line first gets the whole cents of its exact share
982	     * (rounded down), then the cents left over go one each to the lines with the largest leftover
983	     * fractions; between equal fractions the cent goes to the line with the larger amount, and between
984	     * equal amounts too to the lower line id. The shares add up to the discount.
985	     */
986	    public List<BigDecimal> discountShares() {
987	        BigInteger discountCents = discount().movePointRight(scale()).toBigIntegerExact();
988	        BigInteger subtotalCents = subtotal().movePointRight(scale()).toBigIntegerExact();
989	        int n = lines.size();
990	        BigInteger[] shares = new BigInteger[n];
991	        BigInteger[] leftovers = new BigInteger[n];
992	        BigInteger given = BigInteger.ZERO;
993	        for (int i = 0; i < n; i++) {
994	            if (subtotalCents.signum() == 0) {
995	                shares[i] = BigInteger.ZERO;
996	                leftovers[i] = BigInteger.ZERO;
997	            } else {
998	                // The exact share is discount * amount / subtotal; all fractions share the subtotal
999	                // as denominator, so the remainders compare as the fractions do.
1000	                BigInteger[] qr = discountCents.multiply(lines.get(i).amount(scale()).movePointRight(scale()).toBigIntegerExact())
1001	                        .divideAndRemainder(subtotalCents);
1002	                shares[i] = qr[0];
1003	                leftovers[i] = qr[1];
1004	            }
1005	            given = given.add(shares[i]);
1006	        }
1007	        List<Integer> order = new ArrayList<>();
1008	        for (int i = 0; i < n; i++) {
1009	            order.add(i);
1010	        }
1011	        order.sort(Comparator.<Integer, BigInteger>comparing(i -> leftovers[i]).reversed()
1012	                .thenComparing(Comparator.<Integer, BigDecimal>comparing(i -> lines.get(i).amount(scale())).reversed())
1013	                .thenComparing(i -> lines.get(i).getId(), Comparator.nullsLast(Comparator.naturalOrder())));
1014	        int left = discountCents.subtract(given).intValueExact();
1015	        for (int k = 0; k < left; k++) {
1016	            int i = order.get(k);
1017	            shares[i] = shares[i].add(BigInteger.ONE);
1018	        }
1019	        List<BigDecimal> result = new ArrayList<>(n);
1020	        for (BigInteger share : shares) {
1021	            result.add(new BigDecimal(share, scale()));
1022	        }
1023	        return result;
1024	    }
1025	
1026	    /**
1027	     * Each line's tax, in the order of the lines: the line's own rate (a percentage), or the given
1028	     * workspace rate when it has none, on the line's amount less its share of the discount, rounded
1029	     * half up to the cent. Tax-exempt lines, and every line of a tax-exempt client, have no tax.
1030	     */
1031	    public List<BigDecimal> lineTaxes(BigDecimal taxRate) {
1032	        List<BigDecimal> shares = discountShares();
1033	        List<BigDecimal> taxes = new ArrayList<>(lines.size());
1034	        for (int i = 0; i < lines.size(); i++) {
1035	            InvoiceLine line = lines.get(i);
1036	            taxes.add(clientTaxExempt || line.isTaxExempt() ? zero()
1037	                    : line.amount(scale()).subtract(shares.get(i)).multiply(line.taxRate(taxRate)).divide(BigDecimal.valueOf(100))
1038	                            .setScale(scale(), RoundingMode.HALF_UP));
1039	        }
1040	        return taxes;
1041	    }
1042	
1043	    /** The tax charged at the given rate (a percentage): the sum of the line taxes. */
1044	    public BigDecimal tax(BigDecimal taxRate) {
1045	        return lineTaxes(taxRate).stream().reduce(zero(), BigDecimal::add);
1046	    }
1047	
1048	    /** The grand total: the subtotal less the discount, plus tax at the given rate. */
1049	    public BigDecimal total(BigDecimal taxRate) {
1050	        return subtotal().subtract(discount()).add(tax(taxRate));
1051	    }
1052	}
